<template>
    <div>
        <button
            ref="trigger"
            type="button"
            :class="triggerClass"
            :aria-label="label"
            :disabled="disabled"
            aria-expanded="false"
            data-bs-toggle="menu"
            :data-bs-placement="menuPlacement"
        >
            <slot name="trigger">
                <i class="material-icons" aria-hidden="true">more_vert</i>
            </slot>
        </button>

        <div class="menu" :class="contentClasses" :style="{ '--menu-min-width': menuWidth }">
            <slot>
                <slot name="content" />
            </slot>
        </div>
    </div>
</template>

<script>
export default {
    name: 'Dropdown',
    props: {
        label: { type: String, default: 'Izvēlne' },
        align: { type: String, default: 'right' },
        placement: String,
        width: { type: String, default: '12rem' },
        triggerClass: { type: String, default: 'btn-icon' },
        contentClasses: String,
        disabled: Boolean,
    },
    data() {
        return { menuPlugin: null };
    },
    computed: {
        menuPlacement() {
            return this.placement || (['left', 'start'].includes(this.align) ? 'bottom-start' : 'bottom-end');
        },
        menuWidth() {
            return this.width === '48' ? '12rem' : this.width;
        },
    },
    async mounted() {
        const { Menu } = await import('bootstrap');
        this.menuPlugin = Menu;
    },
    beforeUnmount() {
        this.menuPlugin?.getInstance(this.$refs.trigger)?.dispose();
    },
};
</script>
